// Pseudo-code: tenant routing and masking in Dataflow
function processEvent(event) {
  const tenantId = event.tenant_id;
  const masked = maskPII(event); // DLP API or custom UDF
  return {
    tenant: tenantId,
    data: masked,
    timestamp: event.event_time,
    lineage: {pipeline: 'stream-analytics', source: 'pubsub'}
  };
}
